FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector : INT;          // Selector de modo (0: automático, 1: manual, 2: mantenimiento)
    estadoSeguro : BOOL;      // Estado de seguridad activo/inactivo
    cmdAuto : ARRAY[0..7] OF BOOL;  // Comandos para modo automático
    cmdManual : ARRAY[0..7] OF BOOL;  // Comandos para modo manual
    idxForzado : INT;        // Índice del actuador a forzar en modo mantenimiento
    valorForzado : BOOL;      // Valor a forzar en el actuador seleccionado
    confirmarForzado : BOOL;  // Confirmación de forzado
END_VAR

VAR_OUTPUT
    modoActivo : INT;         // Modo de operación activo
    actuador : ARRAY[0..7] OF BOOL;  // Estado de los actuadores
END_VAR

VAR
    modoAnterior : INT;       // Modo anterior para comparación
    forzado : ARRAY[0..7] OF BOOL;  // Estado de forzado de los actuadores
END_VAR

// Inicialización en el arranque
IF NOT estadoSeguro THEN
    modoActivo := 1;  // Modo manual por defecto
ELSE
    modoAnterior := modoActivo;
    CASE selector OF
        0..2: modoActivo := selector;  // Cambio de modo si el selector está en un valor válido
        ELSE modoActivo := modoAnterior;  // Mantener modo anterior si el selector está fuera de rango
    END_CASE;
END_IF;

// Gestión de los actuadores según el modo
CASE modoActivo OF
    0:  // Modo automático
        FOR i := 0 TO 7 DO
            actuador[i] := cmdAuto[i];
        END_FOR;
    1:  // Modo manual
        FOR i := 0 TO 7 DO
            actuador[i] := cmdManual[i];
        END_FOR;
    2:  // Modo mantenimiento
        IF NOT estadoSeguro THEN
            FOR i := 0 TO 7 DO
                actuador[i] := FALSE;
                forzado[i] := FALSE;
            END_FOR;
        ELSE
            IF confirmarForzado THEN
                IF idxForzado >= 0 AND idxForzado <= 7 THEN
                    actuador[idxForzado] := valorForzado;
                    forzado[idxForzado] := TRUE;
                END_IF;
            END_IF;
        END_IF;
END_CASE;

// Anulación de forzados al salir del modo mantenimiento
IF modoAnterior = 2 AND modoActivo <> 2 THEN
    FOR i := 0 TO 7 DO
        forzado[i] := FALSE;
    END_FOR;
END_IF;

// Anulación de forzados si estadoSeguro se desactiva durante el mantenimiento
IF modoActivo = 2 AND NOT estadoSeguro THEN
    FOR i := 0 TO 7 DO
        actuador[i] := FALSE;
        forzado[i] := FALSE;
    END_FOR;
END_IF;

modoAnterior := modoActivo;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector : INT; // Selector de modo de operación
    estadoSeguro : BOOL; // Indica si es seguro cambiar de modo
    cmdAuto : ARRAY[0..7] OF BOOL; // Comandos automáticos para los actuadores
    cmdManual : ARRAY[0..7] OF BOOL; // Comandos manuales para los actuadores
    idxForzado : INT; // Índice del actuador a forzar
    valorForzado : BOOL; // Valor a forzar en el actuador
    confirmarForzado : BOOL; // Confirmación de forzado
END_VAR

VAR_OUTPUT
    modoActivo : INT; // Modo de operación actual
    actuador : ARRAY[0..7] OF BOOL; // Estado de los actuadores
END_VAR

VAR
    modoPendiente : INT; // Modo pendiente de activación
    confirmarForzadoAnt : BOOL; // Estado anterior de confirmarForzado
    forzados : ARRAY[0..7] OF BOOL; // Estados forzados de los actuadores
END_VAR

// Inicialización
modoActivo := 1; // Modo inicial es manual
modoPendiente := 1; // Modo pendiente inicial es manual
confirmarForzadoAnt := FALSE; // Estado inicial de confirmarForzado

// Gestión de modos
IF estadoSeguro THEN
    // Cambiar modo si el selector es válido
    IF (selector >= 0) AND (selector <= 2) THEN
        modoPendiente := selector;
    END_IF;
    modoActivo := modoPendiente;
ELSE
    // Si no es seguro, mantener el modo actual
    modoPendiente := modoActivo;
END_IF;

// Comportamiento según el modo activo
CASE modoActivo OF
    0: // Modo automático
        actuador := cmdAuto;
    1: // Modo manual
        actuador := cmdManual;
    2: // Modo mantenimiento
        // Apagar todos los actuadores si estadoSeguro se desactiva
        IF NOT estadoSeguro THEN
            FOR i := 0 TO 7 DO
                forzados[i] := FALSE;
                actuador[i] := FALSE;
            END_FOR;
        ELSE
            // Gestionar forzados
            IF (confirmarForzado AND NOT confirmarForzadoAnt) THEN
                IF (idxForzado >= 0) AND (idxForzado <= 7) THEN
                    forzados[idxForzado] := valorForzado;
                END_IF;
            END_IF;
            // Aplicar forzados
            FOR i := 0 TO 7 DO
                actuador[i] := forzados[i];
            END_FOR;
        END_IF;
END_CASE;

// Actualizar estado anterior de confirmarForzado
confirmarForzadoAnt := confirmarForzado;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector       : INT;                  (* Selector de modo: 0=Auto, 1=Manual, 2=Mant. *)
    estadoSeguro   : BOOL;                 (* Permiso para cambio de modo y forzados *)
    cmdAuto        : ARRAY[0..7] OF BOOL;  (* Comandos en modo automatico *)
    cmdManual      : ARRAY[0..7] OF BOOL;  (* Comandos en modo manual *)
    idxForzado     : INT;                  (* Indice del actuador a forzar (0..7) *)
    valorForzado   : BOOL;                 (* Valor a aplicar al actuador forzado *)
    confirmarForzado : BOOL;               (* Flanco ascendente aplica el forzado *)
END_VAR
VAR_OUTPUT
    modoActivo : INT;                      (* Modo vigente: 0=Auto, 1=Manual, 2=Mant. *)
    actuador   : ARRAY[0..7] OF BOOL;     (* Estado de los ocho actuadores *)
END_VAR
VAR
    i                  : INT;             (* Indice de bucle *)
    estadosForzados    : ARRAY[0..7] OF BOOL; (* Valores forzados en mantenimiento *)
    confirmarForzado_prev : BOOL;         (* Valor anterior de confirmarForzado *)
    flanco_confirmar   : BOOL;            (* Flanco ascendente detectado *)
    primerCiclo        : BOOL := TRUE;    (* Bandera de primer ciclo para inicializacion *)
    estadoSeguro_prev  : BOOL;            (* Valor anterior de estadoSeguro *)
END_VAR

(* --- Inicializacion en el primer ciclo: modo manual por defecto --- *)
IF primerCiclo THEN
    modoActivo        := 1;
    primerCiclo       := FALSE;
    confirmarForzado_prev := confirmarForzado;
    estadoSeguro_prev := estadoSeguro;
    FOR i := 0 TO 7 DO
        estadosForzados[i] := FALSE;
        actuador[i]        := FALSE;
    END_FOR;
END_IF;

(* --- Gestion del cambio de modo --- *)
(* Solo se acepta un selector valido (0..2) y con estadoSeguro activo *)
IF estadoSeguro AND (selector >= 0) AND (selector <= 2) THEN
    IF selector <> modoActivo THEN
        (* Al salir de mantenimiento, anular todos los forzados *)
        IF modoActivo = 2 THEN
            FOR i := 0 TO 7 DO
                estadosForzados[i] := FALSE;
            END_FOR;
        END_IF;
        modoActivo := selector;
        (* Al entrar en mantenimiento, apagar todos los actuadores *)
        IF modoActivo = 2 THEN
            FOR i := 0 TO 7 DO
                actuador[i]        := FALSE;
                estadosForzados[i] := FALSE;
            END_FOR;
        END_IF;
    END_IF;
END_IF;

(* --- Logica especifica de mantenimiento --- *)
IF modoActivo = 2 THEN
    (* Si estadoSeguro se desactiva durante mantenimiento: anular forzados y apagar *)
    IF (NOT estadoSeguro) AND estadoSeguro_prev THEN
        FOR i := 0 TO 7 DO
            estadosForzados[i] := FALSE;
            actuador[i]        := FALSE;
        END_FOR;
    END_IF;

    (* Detectar flanco ascendente de confirmarForzado *)
    flanco_confirmar := confirmarForzado AND (NOT confirmarForzado_prev);

    (* Aplicar forzado solo si estadoSeguro activo, flanco detectado e indice valido *)
    IF estadoSeguro AND flanco_confirmar
       AND (idxForzado >= 0) AND (idxForzado <= 7) THEN
        estadosForzados[idxForzado] := valorForzado;
    END_IF;

    (* Los actuadores reflejan los valores forzados *)
    FOR i := 0 TO 7 DO
        actuador[i] := estadosForzados[i];
    END_FOR;

(* --- Modo automatico --- *)
ELSIF modoActivo = 0 THEN
    FOR i := 0 TO 7 DO
        actuador[i] := cmdAuto[i];
    END_FOR;

(* --- Modo manual --- *)
ELSIF modoActivo = 1 THEN
    FOR i := 0 TO 7 DO
        actuador[i] := cmdManual[i];
    END_FOR;
END_IF;

(* --- Actualizar valores previos para el proximo ciclo --- *)
confirmarForzado_prev := confirmarForzado;
estadoSeguro_prev     := estadoSeguro;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector : INT; // Selector de modo de operación
    estadoSeguro : BOOL; // Indica si es seguro cambiar de modo
    cmdAuto : ARRAY[0..7] OF BOOL; // Comandos en modo automático
    cmdManual : ARRAY[0..7] OF BOOL; // Comandos en modo manual
    idxForzado : INT; // Índice del actuador a forzar
    valorForzado : BOOL; // Valor a forzar en el actuador
    confirmarForzado : BOOL; // Confirmación de forzado
END_VAR

VAR_OUTPUT
    modoActivo : INT; // Modo de operación activo
    actuador : ARRAY[0..7] OF BOOL; // Estado de los actuadores
END_VAR

VAR
    modoPendiente : INT; // Modo pendiente de aplicar
    confirmarForzadoAnt : BOOL; // Estado anterior de confirmarForzado
    forzadoActivo : ARRAY[0..7] OF BOOL; // Indica si un actuador está forzado
END_VAR

// Inicialización
modoActivo := 1; // Inicia en modo manual
modoPendiente := 1; // Modo pendiente inicial
confirmarForzadoAnt := FALSE; // Estado inicial de confirmarForzado

// Gestión de modos
IF estadoSeguro THEN
    // Cambiar modo si el selector es válido
    IF (selector >= 0) AND (selector <= 2) THEN
        modoPendiente := selector;
    END_IF;
    modoActivo := modoPendiente;
ELSE
    // Si no es seguro, mantener el modo actual
    modoPendiente := modoActivo;
END_IF;

// Comportamiento según el modo activo
CASE modoActivo OF
    0: // Modo automático
        actuador := cmdAuto;
    1: // Modo manual
        actuador := cmdManual;
    2: // Modo mantenimiento
        // Apagar todos los actuadores si estadoSeguro es FALSE
        IF NOT estadoSeguro THEN
            FOR i := 0 TO 7 DO
                actuador[i] := FALSE;
                forzadoActivo[i] := FALSE;
            END_FOR;
        ELSE
            // Gestionar forzado
            IF (NOT confirmarForzadoAnt) AND confirmarForzado THEN
                IF (idxForzado >= 0) AND (idxForzado <= 7) THEN
                    actuador[idxForzado] := valorForzado;
                    forzadoActivo[idxForzado] := TRUE;
                END_IF;
            END_IF;
        END_IF;
END_CASE;

// Actualizar el estado anterior de confirmarForzado
confirmarForzadoAnt := confirmarForzado;

// Al salir del modo mantenimiento, anular todos los forzados
IF modoActivo <> 2 THEN
    FOR i := 0 TO 7 DO
        forzadoActivo[i] := FALSE;
    END_FOR;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector       : INT;                  (* Selector de modo: 0=Auto, 1=Manual, 2=Mantenimiento *)
    estadoSeguro   : BOOL;                 (* Permiso para cambiar modo y mantener forzados *)
    cmdAuto        : ARRAY[0..7] OF BOOL;  (* Comandos en modo automatico *)
    cmdManual      : ARRAY[0..7] OF BOOL;  (* Comandos en modo manual *)
    idxForzado     : INT;                  (* Indice del actuador a forzar (0..7) *)
    valorForzado   : BOOL;                 (* Valor a aplicar al actuador forzado *)
    confirmarForzado : BOOL;               (* Flanco ascendente aplica el forzado *)
END_VAR
VAR_OUTPUT
    modoActivo : INT;                      (* Modo vigente: 0=Auto, 1=Manual, 2=Mantenimiento *)
    actuador   : ARRAY[0..7] OF BOOL;      (* Estado de los ocho actuadores *)
END_VAR
VAR
    modoInterno        : INT := 1;         (* Modo interno; arranca en manual *)
    estadoSeguroPrev   : BOOL;             (* Valor anterior de estadoSeguro *)
    confirmarForzadoPrev : BOOL;           (* Valor anterior de confirmarForzado para deteccion de flanco *)
    estadoForzado      : ARRAY[0..7] OF BOOL; (* Valores forzados en mantenimiento *)
    i                  : INT;             (* Indice de iteracion *)
    primeraEjecucion   : BOOL := TRUE;    (* Bandera de primera ejecucion *)
END_VAR

(* --- Inicializacion en primera ejecucion --- *)
IF primeraEjecucion THEN
    modoInterno      := 1; (* Manual por defecto *)
    primeraEjecucion := FALSE;
END_IF;

(* --- Gestion de cambio de modo --- *)
(* Solo se acepta un nuevo modo si estadoSeguro esta activo y el valor es valido (0..2) *)
IF estadoSeguro AND (selector >= 0) AND (selector <= 2) AND (selector <> modoInterno) THEN
    (* Al salir de mantenimiento, anular todos los forzados *)
    IF modoInterno = 2 THEN
        FOR i := 0 TO 7 DO
            estadoForzado[i] := FALSE;
        END_FOR;
    END_IF;
    modoInterno := selector;
END_IF;

(* --- Deteccion de flanco descendente en estadoSeguro durante mantenimiento --- *)
(* Si estadoSeguro se desactiva en modo mantenimiento, apagar todos los actuadores forzados *)
IF (NOT estadoSeguro) AND estadoSeguroPrev AND (modoInterno = 2) THEN
    FOR i := 0 TO 7 DO
        estadoForzado[i] := FALSE;
    END_FOR;
END_IF;
estadoSeguroPrev := estadoSeguro;

(* --- Logica segun modo activo --- *)
CASE modoInterno OF

    0: (* Modo automatico: actuadores siguen cmdAuto *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdAuto[i];
        END_FOR;

    1: (* Modo manual: actuadores siguen cmdManual *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdManual[i];
        END_FOR;

    2: (* Modo mantenimiento *)
        (* Forzado individual con flanco ascendente de confirmarForzado *)
        (* Solo se procesa si estadoSeguro esta activo *)
        IF estadoSeguro AND confirmarForzado AND (NOT confirmarForzadoPrev) THEN
            IF (idxForzado >= 0) AND (idxForzado <= 7) THEN
                estadoForzado[idxForzado] := valorForzado;
            END_IF;
        END_IF;
        (* Los actuadores reflejan el estado forzado *)
        FOR i := 0 TO 7 DO
            actuador[i] := estadoForzado[i];
        END_FOR;

END_CASE;

(* --- Actualizar flanco de confirmarForzado --- *)
confirmarForzadoPrev := confirmarForzado;

(* --- Reportar modo vigente --- *)
modoActivo := modoInterno;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector : INT; (* Selector de modo *)
    estadoSeguro : BOOL; (* Estado seguro *)
    cmdAuto : ARRAY[0..7] OF BOOL; (* Comandos automáticos para los actuadores *)
    cmdManual : ARRAY[0..7] OF BOOL; (* Comandos manuales para los actuadores *)
    idxForzado : INT; (* Índice del actuador a forzar *)
    valorForzado : BOOL; (* Valor a forzar en el actuador *)
    confirmarForzado : BOOL; (* Confirmación de forzado *)
END_VAR
VAR_OUTPUT
    modoActivo : INT; (* Modo activo *)
    actuador : ARRAY[0..7] OF BOOL; (* Estado de los actuadores *)
END_VAR
VAR
    modoVigente : INT := 1; (* Modo vigente inicializado a manual *)
    forzado : ARRAY[0..7] OF BOOL := [FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE]; (* Estado de forzado de los actuadores *)
END_VAR

(* Gestión de modos *)
IF estadoSeguro THEN
    CASE selector OF
        0: modoVigente := 0; (* Modo automático *)
        1: modoVigente := 1; (* Modo manual *)
        2: modoVigente := 2; (* Modo mantenimiento *)
    END_CASE;
END_IF;

(* Mantener el modo vigente si el selector está fuera de rango *)
IF selector < 0 OR selector > 2 THEN
    modoVigente := modoVigente;
END_IF;

(* Aplicar el modo vigente *)
modoActivo := modoVigente;

(* Gestión de actuadores según el modo *)
CASE modoActivo OF
    0: (* Modo automático *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdAuto[i];
        END_FOR;
    1: (* Modo manual *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdManual[i];
        END_FOR;
    2: (* Modo mantenimiento *)
        FOR i := 0 TO 7 DO
            actuador[i] := FALSE;
        END_FOR;
        IF confirmarForzado THEN
            IF idxForzado >= 0 AND idxForzado <= 7 THEN
                actuador[idxForzado] := valorForzado;
                forzado[idxForzado] := TRUE;
            END_IF;
        END_IF;
        IF NOT estadoSeguro THEN
            FOR i := 0 TO 7 DO
                actuador[i] := FALSE;
                forzado[i] := FALSE;
            END_FOR;
        END_IF;
END_CASE;

(* Anular forzados al salir del modo mantenimiento *)
IF modoActivo <> 2 THEN
    FOR i := 0 TO 7 DO
        forzado[i] := FALSE;
    END_FOR;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector : INT; (* 0=Auto, 1=Manual, 2=Mantenimiento *)
    estadoSeguro : BOOL; (* Condicion para cambiar de modo o mantener forzados *)
    cmdAuto : ARRAY[0..7] OF BOOL; (* Comandos en modo automatico *)
    cmdManual : ARRAY[0..7] OF BOOL; (* Comandos en modo manual *)
    idxForzado : INT; (* Indice del actuador a forzar (0-7) *)
    valorForzado : BOOL; (* Valor a aplicar en el forzado *)
    confirmarForzado : BOOL; (* Flanco de subida para aplicar forzado *)
END_VAR
VAR_OUTPUT
    modoActivo : INT := 1; (* Modo vigente, inicia en manual (1) *)
    actuador : ARRAY[0..7] OF BOOL; (* Estado de los 8 actuadores *)
END_VAR
VAR
    rTrigConfirmar : R_TRIG; (* Detector de flanco para confirmar forzado *)
    i : INT; (* Variable para bucles *)
    modoAnterior : INT := 1; (* Memoria para detectar cambios de modo *)
END_VAR

(* 1. Gestion del cambio de modo *)
IF estadoSeguro THEN
    IF (selector >= 0) AND (selector <= 2) THEN
        modoActivo := selector;
    END_IF;
END_IF;

(* 2. Deteccion de flanco para la confirmacion del forzado *)
rTrigConfirmar(CLK := confirmarForzado);

(* 3. Inicializacion al entrar al modo mantenimiento *)
IF (modoActivo = 2) AND (modoAnterior <> 2) THEN
    FOR i := 0 TO 7 DO
        actuador[i] := FALSE;
    END_FOR;
END_IF;
modoAnterior := modoActivo;

(* 4. Control de actuadores segun el modo activo *)
CASE modoActivo OF
    0: (* Modo Automatico *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdAuto[i];
        END_FOR;

    1: (* Modo Manual *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdManual[i];
        END_FOR;

    2: (* Modo Mantenimiento *)
        IF NOT estadoSeguro THEN
            (* Si se pierde la seguridad, se anulan los forzados *)
            FOR i := 0 TO 7 DO
                actuador[i] := FALSE;
            END_FOR;
        ELSIF rTrigConfirmar.Q THEN
            (* Aplicar forzado individual si el indice es valido *)
            IF (idxForzado >= 0) AND (idxForzado <= 7) THEN
                actuador[idxForzado] := valorForzado;
            END_IF;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK

