FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector        : INT;          (* 0=Auto, 1=Manual, 2=Mantenimiento *)
    estadoSeguro    : BOOL;         (* Permiso para cambio de modo y forzados *)
    cmdAuto         : ARRAY[0..7] OF BOOL;   (* Comandos en modo automático *)
    cmdManual       : ARRAY[0..7] OF BOOL;   (* Comandos en modo manual *)
    idxForzado      : INT;          (* Índice del actuador a forzar (0..7) *)
    valorForzado    : BOOL;         (* Valor a aplicar al actuador forzado *)
    confirmarForzado: BOOL;         (* Flanco ascendente aplica el forzado *)
END_VAR

VAR_OUTPUT
    modoActivo  : INT;                      (* Modo vigente: 0, 1 ó 2 *)
    actuador    : ARRAY[0..7] OF BOOL;      (* Estado de los ocho actuadores *)
END_VAR

VAR
    modoInterno         : INT := 1;         (* Modo vigente interno; arranca en Manual *)
    modoPendiente       : BOOL := FALSE;    (* Hay un cambio de modo esperando estadoSeguro *)
    selectorPendiente   : INT := 1;         (* Valor del selector pendiente de aplicar *)
    confirmarForzado_ant: BOOL := FALSE;    (* Valor anterior de confirmarForzado (flanco) *)
    estadoSeguro_ant    : BOOL := FALSE;    (* Valor anterior de estadoSeguro *)
    i                   : INT;              (* Índice de bucle *)
END_VAR

(* ─────────────────────────────────────────────────────────────────────────── *)
(* 1. GESTIÓN DE CAMBIO DE MODO                                                *)
(* ─────────────────────────────────────────────────────────────────────────── *)

(* Solo se consideran valores de selector válidos (0..2) *)
IF selector >= 0 AND selector <= 2 THEN

    IF estadoSeguro THEN
        (* Estado seguro activo: aplicar cambio inmediatamente si es distinto *)
        IF selector <> modoInterno THEN
            (* Salida de mantenimiento: anular todos los forzados *)
            IF modoInterno = 2 THEN
                FOR i := 0 TO 7 DO
                    actuador[i] := FALSE;
                END_FOR;
            END_IF;
            modoInterno := selector;
        END_IF;
        (* Limpiar pendiente si lo hubiera *)
        modoPendiente := FALSE;
    ELSE
        (* Estado seguro inactivo: registrar cambio como pendiente *)
        IF selector <> modoInterno THEN
            modoPendiente    := TRUE;
            selectorPendiente := selector;
        ELSE
            (* El selector volvió al modo vigente; cancelar pendiente *)
            modoPendiente := FALSE;
        END_IF;
    END_IF;

ELSE
    (* Selector fuera de rango: ignorar; cancelar pendiente si lo hubiera *)
    modoPendiente := FALSE;
END_IF;

(* Flanco ascendente de estadoSeguro: aplicar cambio pendiente si procede *)
IF estadoSeguro AND NOT estadoSeguro_ant THEN
    IF modoPendiente AND selectorPendiente >= 0 AND selectorPendiente <= 2 THEN
        IF selectorPendiente <> modoInterno THEN
            (* Salida de mantenimiento: anular forzados *)
            IF modoInterno = 2 THEN
                FOR i := 0 TO 7 DO
                    actuador[i] := FALSE;
                END_FOR;
            END_IF;
            modoInterno := selectorPendiente;
        END_IF;
        modoPendiente := FALSE;
    END_IF;
END_IF;

(* ─────────────────────────────────────────────────────────────────────────── *)
(* 2. LÓGICA DE ACTUADORES SEGÚN MODO                                          *)
(* ─────────────────────────────────────────────────────────────────────────── *)

CASE modoInterno OF

    (* ── Modo 0: AUTOMÁTICO ── *)
    0:
        FOR i := 0 TO 7 DO
            actuador[i] := cmdAuto[i];
        END_FOR;

    (* ── Modo 1: MANUAL ── *)
    1:
        FOR i := 0 TO 7 DO
            actuador[i] := cmdManual[i];
        END_FOR;

    (* ── Modo 2: MANTENIMIENTO ── *)
    2:
        (* Si estadoSeguro se desactiva: apagar todos los actuadores *)
        IF NOT estadoSeguro THEN
            FOR i := 0 TO 7 DO
                actuador[i] := FALSE;
            END_FOR;
        ELSE
            (* Flanco ascendente de confirmarForzado: aplicar forzado puntual *)
            IF confirmarForzado AND NOT confirmarForzado_ant THEN
                IF idxForzado >= 0 AND idxForzado <= 7 THEN
                    actuador[idxForzado] := valorForzado;
                END_IF;
                (* idxForzado fuera de rango se ignora *)
            END_IF;
        END_IF;

END_CASE;

(* ─────────────────────────────────────────────────────────────────────────── *)
(* 3. ACTUALIZACIÓN DE SALIDA Y MEMORIAS DE FLANCO                             *)
(* ─────────────────────────────────────────────────────────────────────────── *)

modoActivo           := modoInterno;
confirmarForzado_ant := confirmarForzado;
estadoSeguro_ant     := estadoSeguro;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Modos
VAR_INPUT
    selector       : INT;                  (* Selector de modo: 0=Auto, 1=Manual, 2=Mantenimiento *)
    estadoSeguro   : BOOL;                 (* Permiso para cambiar de modo y operar mantenimiento *)
    cmdAuto        : ARRAY[0..7] OF BOOL;  (* Comandos en modo automatico *)
    cmdManual      : ARRAY[0..7] OF BOOL;  (* Comandos en modo manual *)
    idxForzado     : INT;                  (* Indice del actuador a forzar en mantenimiento *)
    valorForzado   : BOOL;                 (* Valor a aplicar al actuador forzado *)
    confirmarForzado : BOOL;               (* Flanco ascendente aplica el forzado *)
END_VAR
VAR_OUTPUT
    modoActivo : INT;                      (* Modo vigente: 0=Auto, 1=Manual, 2=Mantenimiento *)
    actuador   : ARRAY[0..7] OF BOOL;      (* Estado de los ocho actuadores *)
END_VAR
VAR
    prevConfirmar  : BOOL;                 (* Valor anterior de confirmarForzado para deteccion de flanco *)
    estadoForzado  : ARRAY[0..7] OF BOOL;  (* Valores forzados en modo mantenimiento *)
    i              : INT;                  (* Indice auxiliar para bucles *)
    primerCiclo    : BOOL := TRUE;         (* Marca de primer ciclo para inicializacion *)
END_VAR

(* --- Inicializacion en el primer ciclo de ejecucion --- *)
IF primerCiclo THEN
    modoActivo  := 1;   (* Modo inicial: manual *)
    primerCiclo := FALSE;
END_IF;

(* --- Gestion del cambio de modo --- *)
(* Solo se acepta un nuevo modo si estadoSeguro esta activo y el valor es valido (0..2) *)
IF estadoSeguro AND (selector >= 0) AND (selector <= 2) THEN
    IF selector <> modoActivo THEN
        (* Al salir del modo mantenimiento se anulan todos los forzados *)
        IF modoActivo = 2 THEN
            FOR i := 0 TO 7 DO
                estadoForzado[i] := FALSE;
            END_FOR;
        END_IF;
        modoActivo := selector;
    END_IF;
END_IF;

(* --- Logica especifica de cada modo --- *)
CASE modoActivo OF

    0: (* Modo automatico: actuadores siguen cmdAuto *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdAuto[i];
        END_FOR;

    1: (* Modo manual: actuadores siguen cmdManual *)
        FOR i := 0 TO 7 DO
            actuador[i] := cmdManual[i];
        END_FOR;

    2: (* Modo mantenimiento *)
        IF NOT estadoSeguro THEN
            (* Si se pierde el estado seguro, se anulan forzados y se apagan actuadores *)
            FOR i := 0 TO 7 DO
                estadoForzado[i] := FALSE;
                actuador[i]      := FALSE;
            END_FOR;
        ELSE
            (* Deteccion de flanco ascendente en confirmarForzado *)
            IF confirmarForzado AND NOT prevConfirmar THEN
                IF (idxForzado >= 0) AND (idxForzado <= 7) THEN
                    estadoForzado[idxForzado] := valorForzado;
                END_IF;
                (* Indices fuera de rango se ignoran *)
            END_IF;
            (* Los actuadores reflejan el estado forzado acumulado *)
            FOR i := 0 TO 7 DO
                actuador[i] := estadoForzado[i];
            END_FOR;
        END_IF;

END_CASE;

(* --- Actualizacion del valor previo de confirmarForzado --- *)
prevConfirmar := confirmarForzado;

END_FUNCTION_BLOCK

